<div class="content-wrapper"><section class="content-header"><h1>Admin Kapal / Customers</h1></section><section class="content"><?php $this->load->view('pipeline/billing_notice'); ?><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><p>Hubungkan akun Customer ke perusahaan/NIB agar Customer dapat mengelola kapal, legalitas dan pengajuan user milik perusahaannya. Password dan role dikelola melalui Pengaturan User; menu dan area melalui Access Management.</p><a class="btn btn-primary" href="<?= site_url('Pipeline_users/create') ?>">Tambah Akun Customer</a> <a class="btn btn-default" href="<?= site_url('Pipeline_customer_vessels') ?>">Master Kapal Customer</a> <a class="btn btn-default" href="<?= site_url('Superadmin_registration') ?>">Approval Registrasi / Pengajuan User</a></div></div><div class="box"><div class="box-body table-responsive"><table class="table table-bordered"><thead><tr><th>Customer</th><th>Perusahaan / NIB</th><th>Status</th><th>Akses</th></tr></thead><tbody><?php foreach($customers as $c): ?><tr><td><?= html_escape($c['UserName'].' / '.$c['UserID']) ?><br><?= html_escape($c['Email']) ?></td><td><?= html_escape($c['CompanyName']??'Belum dihubungkan') ?><br><?= html_escape($c['NIB']??'') ?></td><td><?= $c['Active']==='1'?'Aktif':'Nonaktif' ?></td><td><a href="<?= site_url('Pipeline_users/edit/'.rawurlencode($c['UserID'])) ?>">Edit User</a> · <a href="<?= site_url('Pipeline_users/access/'.rawurlencode($c['UserID'])) ?>">Access Management</a></td></tr><?php endforeach; ?><?php if(!$customers): ?><tr><td colspan="4">Belum ada akun Customer.</td></tr><?php endif; ?></tbody></table></div></div><div class="box box-success"><div class="box-header"><h3 class="box-title">Hubungkan Customer ke Perusahaan</h3></div><div class="box-body"><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><div class="form-group"><label>Akun Customer</label><select id="customer-account-select" name="UserID" class="form-control" required><option value="">Pilih Customer</option><?php foreach($customers as $c): ?><option value="<?= html_escape($c['UserID']) ?>" data-version="<?= (int)$c['AccessVersion'] ?>" data-nib="<?= html_escape($c['NIB']??'') ?>" data-company="<?= html_escape($c['CompanyName']??'') ?>"><?= html_escape($c['UserName'].' / '.$c['UserID']) ?></option><?php endforeach; ?></select></div><input id="customer-account-version" name="AccessVersion" type="hidden"><div class="row"><div class="col-md-6 form-group"><label>NIB Perusahaan</label><input id="customer-account-nib" name="NIB" pattern="[0-9]{5,20}" maxlength="20" required class="form-control" list="customer-company-nibs"><datalist id="customer-company-nibs"><?php foreach($entities as $e): ?><option value="<?= html_escape($e['NIB']) ?>" data-company="<?= html_escape($e['CompanyName']) ?>"><?= html_escape($e['CompanyName']) ?></option><?php endforeach; ?></datalist></div><div class="col-md-6 form-group"><label>Nama Perusahaan</label><input id="customer-account-company" name="CompanyName" maxlength="150" required class="form-control"></div></div><p class="text-muted">NIB baru membuat badan usaha baru. Untuk NIB yang sudah ada, gunakan nama perusahaan terdaftar.</p><button class="btn btn-success">Simpan Hubungan Perusahaan</button></form></div></div><?php $this->load->view('pipeline/customer_company_history'); ?></section></div><script>(function(){var s=document.getElementById('customer-account-select'),n=document.getElementById('customer-account-nib'),c=document.getElementById('customer-account-company');s.addEventListener('change',function(){var o=s.options[s.selectedIndex];document.getElementById('customer-account-version').value=o.dataset.version||'';n.value=o.dataset.nib||'';c.value=o.dataset.company||'';});n.addEventListener('input',function(){var opts=document.getElementById('customer-company-nibs').options;for(var i=0;i<opts.length;i++)if(opts[i].value===n.value)c.value=opts[i].dataset.company;});})();</script>